public function readAnimationData(byteArray:ByteArray) : AnimClipDef
{
   var currentPosition:int = byteArray.position;
   this.animationId = byteArray.readUTF();
   this.url = byteArray.readUTF();
   var options:uint = byteArray.readUnsignedByte();
   this.isLooping = 0 != (options & 1);
   this.hasSpriteSheet = 0 != (options & 2);
   this.isHighQuality = 0 != (options & 4);
   this.isPngEncoded = 0 != (options & 8);
   var hasScale:* = 0 != (options & 16);
   var hasOffsetX:* = 0 != (options & 32);
   var hasOffsetY:* = 0 != (options & 64);
   var hasShrunkenScale:* = 0 != (options & 128);
   if(this.url.indexOf(".portrait/") > 0)
   {
      this.isLooping = true;
   }
   if(hasScale)
   {
      this.scale = byteArray.readFloat();
   }
   if(hasOffsetX)
   {
      this.offsetX = byteArray.readFloat();
   }
   if(hasOffsetY)
   {
      this.offsetY = byteArray.readFloat();
   }
   if(hasShrunkenScale)
   {
      this.shrunkenScale = byteArray.readFloat();
   }
   var frameCount:int = byteArray.readUnsignedShort();
   var frameRate:int = byteArray.readUnsignedByte();
   this.setup(frameCount, frameRate);
   this.animFrames = new AnimFrames(this, this.logger);
   this.animFrames.readBytes(byteArray, currentPosition);
   this.locomotiveTilesTotal = this.animFrames.locomotiveTilesTotal;
   if(this.locomotiveTilesTotal)
   {
      this.setup(this.numFrames, this.fps);
   }
   return this;
}
